// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Inicia sessão com e-mail e palavra-passe
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Termina a sessão
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RefreshSession Renova a sessão com o refresh token do cookie
	// (POST /auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// ListCategories Lista as categorias, com o número de produtos de cada uma
	// (GET /categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// CreateCategory Cria uma categoria
	// (POST /categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// DeleteCategory Apaga uma categoria sem produtos
	// (DELETE /categories/{id})
	DeleteCategory(ctx context.Context, request DeleteCategoryRequestObject) (DeleteCategoryResponseObject, error)
	// RenameCategory Muda o nome de uma categoria
	// (PATCH /categories/{id})
	RenameCategory(ctx context.Context, request RenameCategoryRequestObject) (RenameCategoryResponseObject, error)
	// GetHealth O processo está vivo
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// RunStockAlerts Envia o alerta diário de stock (chamado pelo agendamento)
	// (POST /jobs/stock-alerts)
	RunStockAlerts(ctx context.Context, request RunStockAlertsRequestObject) (RunStockAlertsResponseObject, error)
	// GetMe Utilizador da sessão atual
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListProducts Lista todos os produtos, ativos e inativos
	// (GET /products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// CreateProduct Cria um produto
	// (POST /products)
	CreateProduct(ctx context.Context, request CreateProductRequestObject) (CreateProductResponseObject, error)
	// DeleteProduct Apaga um produto sem histórico
	// (DELETE /products/{id})
	DeleteProduct(ctx context.Context, request DeleteProductRequestObject) (DeleteProductResponseObject, error)
	// GetProduct Um produto, com o ETag para o editar
	// (GET /products/{id})
	GetProduct(ctx context.Context, request GetProductRequestObject) (GetProductResponseObject, error)
	// UpdateProduct Substitui os dados de um produto
	// (PUT /products/{id})
	UpdateProduct(ctx context.Context, request UpdateProductRequestObject) (UpdateProductResponseObject, error)
	// DeleteProductImage Remove a imagem do produto
	// (DELETE /products/{id}/image)
	DeleteProductImage(ctx context.Context, request DeleteProductImageRequestObject) (DeleteProductImageResponseObject, error)
	// PutProductImage Troca a imagem do produto
	// (PUT /products/{id}/image)
	PutProductImage(ctx context.Context, request PutProductImageRequestObject) (PutProductImageResponseObject, error)
	// GetPublicCatalog Catálogo público (sem sessão)
	// (GET /public/catalog)
	GetPublicCatalog(ctx context.Context, request GetPublicCatalogRequestObject) (GetPublicCatalogResponseObject, error)
	// GetProductImage Imagem de um produto (pública, imutável)
	// (GET /public/products/{id}/image)
	GetProductImage(ctx context.Context, request GetProductImageRequestObject) (GetProductImageResponseObject, error)
	// GetReadiness O processo está pronto (BD acessível)
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// GetStockOverview Consulta do stock por produto e por lote
	// (GET /stock)
	GetStockOverview(ctx context.Context, request GetStockOverviewRequestObject) (GetStockOverviewResponseObject, error)
	// CreateStockAdjustment Regista um ajuste ou uma quebra num lote
	// (POST /stock/adjustments)
	CreateStockAdjustment(ctx context.Context, request CreateStockAdjustmentRequestObject) (CreateStockAdjustmentResponseObject, error)
	// ListStockLots Lotes de um produto
	// (GET /stock/lots)
	ListStockLots(ctx context.Context, request ListStockLotsRequestObject) (ListStockLotsResponseObject, error)
	// CreateStockLot Regista uma entrada de stock (um lote)
	// (POST /stock/lots)
	CreateStockLot(ctx context.Context, request CreateStockLotRequestObject) (CreateStockLotResponseObject, error)
	// ListUsers Lista os utilizadores, ativos e desativados
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Cria um utilizador
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// UpdateUser Edita um utilizador (nome, papel, estado ou palavra-passe)
	// (PATCH /users/{id})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

